import type {
  DarkModeStrategyName,
  SemanticColorToken,
  ThemeName,
} from './tokens'

import { nativeAliasTokens, semanticColorTokens } from './tokens'

export interface ThemeCssOptions {
  /**
   * Dark mode selector strategy. `class` is the default and matches the
   * `.dark` convention used by both the package CSS and the registry.
   */
  darkMode?: DarkModeStrategyName
}

/** Marker read by `scripts/emit-theme-css.ts` to keep generated files honest. */
export const generatedThemeCssMarker = '/* Generated by @zeus-web/themes'

const colorSchemeLight = 'light'
const colorSchemeDark = 'dark'

function renderTokenLines(
  colors: Record<SemanticColorToken, string>,
  colorScheme: string,
): string[] {
  return [
    `  color-scheme: ${colorScheme};`,
    ...semanticColorTokens.map(token => `  --${token}: ${colors[token]};`),
    ...nativeAliasTokens.map(token => `  --zw-${token}: var(--${token});`),
    ...semanticColorTokens.map(token => `  --zeus-${token}: var(--${token});`),
  ]
}

function renderLightBlock(
  name: string,
  colors: Record<SemanticColorToken, string>,
): string[] {
  return [
    ':root,',
    `[data-theme='${name}'] {`,
    ...renderTokenLines(colors, colorSchemeLight),
    '}',
  ]
}

function renderDarkBlock(
  name: string,
  colors: Record<SemanticColorToken, string>,
  darkMode: DarkModeStrategyName,
): string[] {
  const body = renderTokenLines(colors, colorSchemeDark)

  if (darkMode === 'media') {
    return [
      '@media (prefers-color-scheme: dark) {',
      '  :root,',
      `  [data-theme='${name}'] {`,
      ...body.map(line => `  ${line}`),
      '  }',
      '}',
    ]
  }

  if (darkMode === 'data') {
    return [
      ":root[data-mode='dark'],",
      `[data-theme='${name}'][data-mode='dark'] {`,
      ...body,
      '}',
    ]
  }

  return [
    '.dark,',
    `[data-theme='${name}'].dark,`,
    `.dark [data-theme='${name}'] {`,
    ...body,
    '}',
  ]
}

/**
 * Renders one theme block (without the `@import` of `tokens.css`).
 * Shared by the built-in theme files and `createThemeCss`.
 */
export function createThemeBlockCss(params: {
  name: string
  light: Record<SemanticColorToken, string>
  dark: Record<SemanticColorToken, string>
  baseTheme?: string
  darkMode?: DarkModeStrategyName
}): string {
  const { name, light, dark } = params
  const darkMode: DarkModeStrategyName = params.darkMode ?? 'class'
  const header =
    params.baseTheme === undefined
      ? `${generatedThemeCssMarker} from palettes.ts. Do not edit by hand. */`
      : `/* Generated by @zeus-web/themes from ${params.baseTheme}. */`

  return [
    header,
    ...renderLightBlock(name, light),
    '',
    ...renderDarkBlock(name, dark, darkMode),
    '',
  ].join('\n')
}

/** Full built-in theme file, including the `tokens.css` import. */
export function createBuiltinThemeFileCss(
  name: ThemeName,
  palettes: {
    light: Record<SemanticColorToken, string>
    dark: Record<SemanticColorToken, string>
  },
): string {
  return [
    "@import './tokens.css';",
    '',
    createThemeBlockCss({ name, light: palettes.light, dark: palettes.dark }),
  ].join('\n')
}
